function recheckCompetitionDeadlines(opportunities) {
  const now = (/* @__PURE__ */ new Date()).toISOString();
  const competitions = opportunities.filter(
    (o) => (o.category || "").toLowerCase().includes("competition") || (o.opportunityType || "").toLowerCase().includes("competition") || (o.subcategory || "").toLowerCase().includes("competition")
  );
  const updatedItems = [];
  let activeCount = 0;
  let closedCount = 0;
  let flaggedCount = 0;
  for (const comp of competitions) {
    const deadlineInfo = calculateDeadlineInfo(comp.deadline);
    if (deadlineInfo.isClosed && comp.status !== "closed" && comp.status !== "archived") {
      updatedItems.push({
        id: comp.id,
        title: comp.title,
        oldStatus: comp.status,
        newStatus: "closed",
        reason: "Registration deadline has expired"
      });
      closedCount++;
    } else if (comp.status === "published" || comp.status === "approved") {
      activeCount++;
      if (deadlineInfo.daysLeft <= 3) {
        flaggedCount++;
      }
    }
  }
  return {
    checkedCount: competitions.length,
    activeCount,
    closedCount,
    flaggedCount,
    timestamp: now,
    updatedItems
  };
}

