async function safeGoogleSheetsFetch(url, options = {}, context2 = "Google Sheets API") {
  let resp;
  try {
    resp = await fetch(url, options);
  } catch (netErr) {
    throw new Error(`Connection to ${context2} failed: ${netErr.message}`);
  }
  const contentType = (resp.headers.get("content-type") || "").toLowerCase();
  const rawBody = await resp.text();
  let parsed = null;
  if (rawBody && rawBody.trim()) {
    if (contentType.includes("application/json") || rawBody.trim().startsWith("{") || rawBody.trim().startsWith("[")) {
      try {
        parsed = JSON.parse(rawBody);
      } catch {
        parsed = { rawText: rawBody };
      }
    } else {
      parsed = { rawText: rawBody };
    }
  }
  if (!resp.ok) {
    const googleMsg = parsed?.error?.message || parsed?.error_description || parsed?.message || parsed?.rawText || `HTTP ${resp.status}`;
    let guidance = "";
    if (resp.status === 401) {
      guidance = " (Authentication token expired. Please reconnect Google Sheets.)";
    } else if (resp.status === 403) {
      guidance = " (Permission denied. Ensure the Google Sheets API is enabled in your Google Cloud project and that the connected Google account has Editor access to this spreadsheet.)";
    } else if (resp.status === 404) {
      guidance = " (Spreadsheet or worksheet not found. Verify the spreadsheet ID and tab name.)";
    } else if (resp.status === 429) {
      guidance = " (Google Sheets API quota exceeded. Please wait a moment before trying again.)";
    }
    const err = new Error(`${context2} error [HTTP ${resp.status}]: ${googleMsg}${guidance}`);
    err.status = resp.status;
    err.googleError = parsed?.error || parsed;
    throw err;
  }
  return parsed;
}
async function getOrRefreshGoogleAccessToken() {
  const config = googleSheetsConfigState;
  const creds = getGoogleOAuthCredentials();
  if (!config.tokens?.access_token && !config.tokens?.refresh_token) {
    throw new Error('Google Sheets is not connected. Please click "Connect Google Sheets" first.');
  }
  const nowMs = Date.now();
  const expiry = config.tokens.expiry_date || 0;
  if (config.tokens.access_token && expiry > nowMs + 18e4) {
    return config.tokens.access_token;
  }
  if (config.tokens.refresh_token && creds.clientId && creds.clientSecret) {
    try {
      const params = new URLSearchParams({
        client_id: creds.clientId,
        client_secret: creds.clientSecret,
        refresh_token: config.tokens.refresh_token,
        grant_type: "refresh_token"
      });
      const resp = await fetch("https://oauth2.googleapis.com/token", {
        method: "POST",
        headers: { "Content-Type": "application/x-www-form-urlencoded" },
        body: params.toString()
      });
      if (resp.ok) {
        const data = await resp.json();
        const newExpiry = nowMs + (data.expires_in || 3600) * 1e3;
        const updatedConfig = {
          ...config,
          tokens: {
            ...config.tokens,
            access_token: data.access_token,
            expiry_date: newExpiry
          }
        };
        saveGoogleSheetsConfig(updatedConfig);
        return data.access_token;
      }
    } catch (refreshErr) {
      console.warn("[GoogleSheets] Token refresh warning:", refreshErr.message);
    }
  }
  if (config.tokens.access_token) {
    return config.tokens.access_token;
  }
  throw new Error('Google authorization token expired. Please click "Connect Google Sheets" to reconnect.');
}
