app.post("/api/admin/google-sheets/select-spreadsheet", verifyAdminAuth, async (req, res) => {
  try {
    const accessToken = await getOrRefreshGoogleAccessToken();
    const rawIdOrUrl = (req.body?.spreadsheetId || "").trim();
    const customSheetName = (req.body?.sheetName || "").trim();
    if (!rawIdOrUrl) {
      return res.status(400).json({ success: false, error: "Spreadsheet ID or URL is required." });
    }
    let spreadsheetId = rawIdOrUrl;
    const urlMatch = rawIdOrUrl.match(/\/spreadsheets\/d\/([a-zA-Z0-9-_]+)/);
    if (urlMatch && urlMatch[1]) {
      spreadsheetId = urlMatch[1];
    }
    const meta = await safeGoogleSheetsFetch(
      `https://sheets.googleapis.com/v4/spreadsheets/${spreadsheetId}`,
      { headers: { Authorization: `Bearer ${accessToken}` } },
      "Spreadsheet access verification"
    );
    const spreadsheetName = meta.properties?.title || "Connected Spreadsheet";
    const sheetsList = (meta.sheets || []).map((s2) => s2.properties?.title || "Sheet1");
    let sheetName = customSheetName;
    if (!sheetName || !sheetsList.includes(sheetName)) {
      if (sheetsList.includes("Subscribers")) {
        sheetName = "Subscribers";
      } else if (sheetsList.includes("Email Subscribers")) {
        sheetName = "Email Subscribers";
      } else {
        sheetName = sheetsList[0] || "Sheet1";
      }
    }
    const spreadsheetUrl = `https://docs.google.com/spreadsheets/d/${spreadsheetId}`;
    const updatedConfig = {
      ...googleSheetsConfigState,
      spreadsheetId,
      spreadsheetName,
      sheetName,
      spreadsheetUrl
    };
    saveGoogleSheetsConfig(updatedConfig);
    return res.json({
      success: true,
      message: `Connected to spreadsheet "${spreadsheetName}" (worksheet: "${sheetName}").`,
      spreadsheetId,
      spreadsheetName,
      sheetName,
      spreadsheetUrl,
      availableSheets: sheetsList
    });
  } catch (err) {
    console.error("Error selecting spreadsheet:", err);
    return res.status(err.status || 500).json({ success: false, error: err.message || "Could not select spreadsheet" });
  }
});
